+        return new CartesianPoint(x, y);
+    }
+
+    @Override
+    protected double planeDistance(double x1, double y1, CartesianPoint point) {
+        double x = point.getX() - x1;
+        double y = point.getY() - y1;
+        return Math.sqrt(x * x + y * y);
